function validate([address]) {
  if (typeof address !== 'string') return 'address must be text.';
  const parts = address.split('.');
  if (parts.length !== 4) return 'address needs exactly four numbers separated by dots.';
  for (const part of parts) {
    if (!/^(0|[1-9][0-9]{0,2})$/.test(part) || Number(part) > 255) return 'Each part is a number from 0 to 255 without leading zeros.';
  }
  return null;
}

