function generate(rand, size) {
  const part = () => {
    const roll = rand();
    if (size === 'small' && roll < 0.2) return 0;
    if (roll < 0.3) return 255;
    if (roll < 0.6) return Math.floor(rand() * 10);
    return Math.floor(rand() * 256);
  };
  return [[part(), part(), part(), part()].join('.')];
}
